; scroller.asm - generated by gen_scroller.py, do not edit
;
; for the Placard CPU (a ROM program that uses the standard library)
;
;     python3 gen_scroller.py                 writes scroller.asm next to this script
;     python3 gen_scroller.py --preview p.png also draws the first frame with the
;                                             Python model (no CPU)
;     python3 test_scroller_sim.py            runs it in placard_sim and checks
;                                             every frame against the model
;
; SCREEN
;     rows   0-31   1 bpp, 1x   four lines of 80 column text: title, score,
;                               controls, CPU load
;     rows  32-479  4 bpp, 4x   the playfield: 160 x 112 pixels of 4 x 4,
;                               16 colors, in four bands:
;         cells   0-23   clouds over the sky       scrolls at 1/8 speed
;         cells  24-47   mountains                 1/4
;         cells  48-63   hills                     1/2
;         cells  64-111  the level: 3 rows of      full speed
;                        16 x 16 tiles
;     The text rows use video offsets x020-x03F of each byte column and the
;     playfield x180-x1FF (docs/VIDEO.md, line repeat).
;
; HOW IT DRAWS A FRAME (no scroll registers, no sprite hardware)
;     Every frame the whole playfield is drawn again, 8,960 bytes, ahead of
;     the video beam:
;       1. Wait for the start of vertical blanking (frame_poll sees the line
;          read wrap).
;       2. Draw the bands top to bottom.  Each band is a repeating picture
;          64 byte columns wide; each distinct byte column of it is a
;          "strip", unrolled code in ROM that stores the column's bytes with
;          immediates (ld X, x / ld value, [y,x]: 6 clocks a byte, because
;          video memory is column-major).  Every row is drawn every frame,
;          even rows that are the same in every column: a sprite can cover
;          any row, and only the redraw takes it away.  The level band is drawn as three tile
;          strips per column (tile id x 8 + byte in the tile).
;          The beam takes 800 clocks a line; the drawing is a band ahead of
;          it all the way down, so nothing tears.
;       3. Draw the sprites on top with a blitter that runs from RAM: it maps
;          the video RAM in (map xFD) so it can read the background, and
;          each sprite frame is compiled code (one routine per frame, made by
;          this script): a store for each solid byte, read / AND mask / OR /
;          write for each byte that is half transparent, nothing for empty
;          bytes.  The row offsets come from a table, so a sprite can be at
;          any row; columns off the screen and rows off the playfield write
;          to video RAM that isn't shown (page x60, offset x10).
;     Then the sound driver, the pads and keyboard, and the game.  The text
;     line 3 shows the CPU load: the share of the frame not spent waiting
;     for the next one.
;
; THE GAME
;     Run right (or left), jump over water and onto bricks, collect coins,
;     stomp the slimes (landing on them; touching one from the side costs a
;     life).  The level is 128 tiles (1,024 bytes) long and wraps around; on
;     each lap the coins and slimes come back.  All positions are 10-bit
;     byte columns, so the wrap is free.  With no input for 10 s the demo
;     player (runs right, jumps at water, walls and slimes) takes over; it
;     starts in the demo.
;     Controls: arrow keys or SNES pad 1 Left / Right, Up / Space / pad B
;     or A to jump.
;
; Date: 10/19/2026

#include "placard.asm"
#include "placard_lib.asm"

; ---------------------------------------------------------------------------
; program variables (zero page x20-x8F)
; ---------------------------------------------------------------------------
colpage    = 0x20       ; video page of the column being drawn (x61 + 2 * col)
rl         = 0x21       ; strip return address
rh         = 0x22
bw         = 0x23       ; band picture column
gt         = 0x24       ; level tile column 0-127
gj         = 0x25       ;   byte in the tile 0-7
tmp        = 0x26
tmp2       = 0x27
scl        = 0x28       ; scroll: world byte column at the left edge, 0-1023
sch        = 0x29
pxl        = 0x2A       ; player x (left byte column), 0-1023
pxh        = 0x2B
pyl        = 0x2C       ; player y: top cell (pyh) and 1/256 cell
pyh        = 0x2D
vyl        = 0x2E       ; vertical speed, cells / 256 a frame, signed
vyh        = 0x2F
onground   = 0x30
facing     = 0x31       ; 0 right, 5 left (frame offset)
anim       = 0x32
inp        = 0x33       ; input: 1 right, 2 left, 4 jump
demo       = 0x34
idle_lo    = 0x35
idle_hi    = 0x36
last_frame = 0x37
lives      = 0x38
score_lo   = 0x39
score_hi   = 0x3A
coins      = 0x3B
hud_dirty  = 0x3C
ta_lo      = 0x3D       ; tile_at: world byte column, cell
ta_hi      = 0x3E
ta_g       = 0x3F
chk_lo     = 0x40       ; where the player last stood
chk_hi     = 0x41
sl_n       = 0x42       ; sprites in the list
s_i        = 0x43
sc         = 0x44       ; this sprite: byte column + 8, top cell + 32
sy         = 0x45
srl        = 0x46       ; return address for the sprite routines
srh        = 0x47
vpg        = 0x48       ; x48-x4F: video page of each of the sprite's 8 columns
SL_LO      = 0x50       ; x50-x5B: sprite routine address, low
SL_HI      = 0x5C       ; x5C-x67: high
SL_C       = 0x68       ; x68-x73: byte column + 8 (0-87)
SL_G       = 0x74       ; x74-x7F: top cell + 32
it_lo      = 0x80       ; polls while waiting for the next frame
it_hi      = 0x81
o_i        = 0x82       ; object loop index
dlo        = 0x83
dhi        = 0x84
inv        = 0x85       ; frames of safety after a lost life
lag        = 0x86       ; frames missed (should stay 0)
moved      = 0x87
tmp3       = 0x88
hud_div    = 0x89
danger     = 0x8A       ; a slime ahead (for the demo player)
ll_lo      = 0x8B       ; lose_life's return address
ll_hi      = 0x8C

draw_sprites = 0x0300       ; in RAM (the blitter)
MODE_PF    = 10
GRAV       = 56
JUMPV_LO   = 128
JUMPV_HI   = 251
MAXFALL_HI = 5
INV_FRAMES = 90
IDLE_TICKS = 600
N_COINS    = 26
N_SLIMES   = 5
MAX_SPR    = 12
GROUND_G   = 64
START_X    = 16
NROW       = 112
ENEMY      = 0x5400       ; RAM: slime state (see the end of this file)
COIN_GOT   = 0x5500       ; RAM: 1 when coin n is taken

; main
#addr 0x6000
main:
    ld   STACK_TOP, ac
    ld   ac, [SP]
    ld   LINK_LO, x             ; CALL port_init
    ld   m_1, [x]
    ld   LINK_HI, x
    ld   m_1 >> 8, [x]
    ld   port_init >> 8, y
    jmp  port_init
m_1:
    ld   LINK_LO, x             ; CALL con_clear
    ld   m_2, [x]
    ld   LINK_HI, x
    ld   m_2 >> 8, [x]
    ld   con_clear >> 8, y
    jmp  con_clear
m_2:
    ld   LINK_LO, x             ; CALL snd_init
    ld   m_3, [x]
    ld   LINK_HI, x
    ld   m_3 >> 8, [x]
    ld   snd_init >> 8, y
    jmp  snd_init
m_3:
    ld   0x5A, y                ; rows 32-479 (x5A40-x5BFF): 4 bpp 4x
    ld   0x40, ac
m_mb1:
    ld   ac, x
    ld   MODE_PF, [y,x]
    inc
    bne  m_mb1
    ld   0x5B, y
    clr  ac
m_mb2:
    ld   ac, x
    ld   MODE_PF, [y,x]
    inc
    bne  m_mb2
    ld   BLIT_ROM & 0xFF, ac    ; copy the RAM blitter, a page at a time
    ld   ac, [R0]
    ld   BLIT_ROM >> 8, ac
    ld   ac, [R1]
    clr  ac
    ld   ac, [R2]
    ld   1, ac
    ld   ac, [R3]
    ld   BLIT_PAGES, ac
    ld   ac, [tmp3]
m_cp:
    clr  ac
    ld   ac, [R4]
    ld   LINK_LO, x             ; CALL memcpy
    ld   m_cp1, [x]
    ld   LINK_HI, x
    ld   m_cp1 >> 8, [x]
    ld   memcpy >> 8, y
    jmp  memcpy
m_cp1:
    ld   [tmp3], ac
    sub  1, ac
    ld   ac, [tmp3]
    beq  m_cp2
    ld   m_cp >> 8, y
    jmp  m_cp
m_cp2:
    ld   m_st1 & 0xFF, ac       ; the rows that never change, every column
    ld   ac, [rl]
    ld   m_st1 >> 8, ac
    ld   ac, [rh]
    ld   0x61, ac
    ld   ac, [colpage]
    ld   strip_static >> 8, y
    jmp  strip_static
m_st1:
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac                  ; past column 79 (xFF + 2 = x01)
    beq  m_st2
    ld   strip_static >> 8, y
    jmp  strip_static
m_st2:
    clr  ac
    ld   ac, [CUR_COL]
    ld   0, ac
    ld   ac, [CUR_ROW]
    ld   s_title, ac
    ld   ac, [R0]
    ld   s_title >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s0, [x]
    ld   LINK_HI, x
    ld   m_s0 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s0:
    clr  ac
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   s_score, ac
    ld   ac, [R0]
    ld   s_score >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s1, [x]
    ld   LINK_HI, x
    ld   m_s1 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s1:
    clr  ac
    ld   ac, [CUR_COL]
    ld   2, ac
    ld   ac, [CUR_ROW]
    ld   s_keys, ac
    ld   ac, [R0]
    ld   s_keys >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s2, [x]
    ld   LINK_HI, x
    ld   m_s2 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s2:
    clr  ac
    ld   ac, [CUR_COL]
    ld   3, ac
    ld   ac, [CUR_ROW]
    ld   s_cpu, ac
    ld   ac, [R0]
    ld   s_cpu >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s3, [x]
    ld   LINK_HI, x
    ld   m_s3 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s3:
    ld   hop_1 >> 8, y
    jmp  hop_1                  ; (to the next page)
#addr 0x6100
hop_1:
    ld   0x20, ac               ; program variables x20-x8F = 0
m_z:
    ld   ac, x
    ld   0, [x]
    add  1, ac
    sub  0x90, ac
    beq  m_z1
    add  0x90, ac
    bra  m_z
m_z1:
    ld   1, ac
    ld   ac, [demo]
    ld   ac, [hud_div]
    ld   ac, [hud_dirty]
    ld   3, ac
    ld   ac, [lives]
    ld   START_X, ac
    ld   ac, [chk_lo]
    ld   LINK_LO, x             ; CALL reset_objs
    ld   m_ro, [x]
    ld   LINK_HI, x
    ld   m_ro >> 8, [x]
    ld   reset_objs >> 8, y
    jmp  reset_objs
m_ro:
    ld   LINK_LO, x             ; CALL respawn
    ld   m_rs, [x]
    ld   LINK_HI, x
    ld   m_rs >> 8, [x]
    ld   respawn >> 8, y
    jmp  respawn
m_rs:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   m_fp, [x]
    ld   LINK_HI, x
    ld   m_fp >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
m_fp:
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
    ld   frame >> 8, y
    jmp  frame

; frame: wait for vertical blanking, then draw ahead of the beam
frame:
    clr  ac
    ld   ac, [it_lo]
    ld   ac, [it_hi]
f_wait:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   f_w1, [x]
    ld   LINK_HI, x
    ld   f_w1 >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
f_w1:
    ld   [it_lo], ac            ; count the polls (CPU load)
    add  1, ac
    ld   ac, [it_lo]
    bcc  f_w2
    ld   [it_hi], ac
    add  1, ac
    ld   ac, [it_hi]
f_w2:
    ld   [FRAME_LO], ac
    sub  [last_frame], ac
    bne  f_new
    ld   f_wait >> 8, y
    jmp  f_wait
f_new:
    sub  1, ac                  ; more than one frame: count the missed ones
    beq  f_nolag
    add  [lag], ac
    ld   ac, [lag]
f_nolag:
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
frame_go:
    ld   [scl], ac              ; w = (scroll >> 3) & 63
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [tmp]
    ld   [sch], ac
    and  1, ac
    beq  bC_o
    ld   [tmp], ac
    or   0x20, ac
    ld   ac, [tmp]
bC_o:
    ld   [tmp], ac
    and  63, ac
    add  0, ac             ; (this band's strips at BS_LO + 0)
    ld   ac, [bw]
    ld   bC_ret & 0xFF, ac
    ld   ac, [rl]
    ld   bC_ret >> 8, ac
    ld   ac, [rh]
    ld   0x61, ac
    ld   ac, [colpage]
bC_lp:
    ld   [bw], x                ; strip for picture column bw
    ld   BS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   BS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
bC_ret:
    ld   [bw], ac
    add  1, ac
    and  63, ac
    or   0, ac
    ld   ac, [bw]
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    bne  bC_lp
band_C_done:
    ld   [scl], ac              ; w = (scroll >> 2) & 63
    shr  ac
    shr  ac
    and  63, ac
    add  64, ac             ; (this band's strips at BS_LO + 64)
    ld   ac, [bw]
    ld   bM_ret & 0xFF, ac
    ld   ac, [rl]
    ld   bM_ret >> 8, ac
    ld   ac, [rh]
    ld   0x61, ac
    ld   ac, [colpage]
    ld   hop_2 >> 8, y
    jmp  hop_2                  ; (to the next page)
#addr 0x6200
hop_2:
bM_lp:
    ld   [bw], x                ; strip for picture column bw
    ld   BS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   BS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
bM_ret:
    ld   [bw], ac
    add  1, ac
    and  63, ac
    or   64, ac
    ld   ac, [bw]
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    bne  bM_lp
band_M_done:
    ld   [scl], ac              ; w = (scroll >> 1) & 63
    shr  ac
    and  63, ac
    add  128, ac             ; (this band's strips at BS_LO + 128)
    ld   ac, [bw]
    ld   bH_ret & 0xFF, ac
    ld   ac, [rl]
    ld   bH_ret >> 8, ac
    ld   ac, [rh]
    ld   0x61, ac
    ld   ac, [colpage]
bH_lp:
    ld   [bw], x                ; strip for picture column bw
    ld   BS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   BS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
bH_ret:
    ld   [bw], ac
    add  1, ac
    and  63, ac
    or   128, ac
    ld   ac, [bw]
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    bne  bH_lp
band_H_done:
    ld   [scl], ac              ; level: tile column = (scroll >> 3) & 127,
    and  7, ac                  ; byte in the tile = scroll & 7
    ld   ac, [gj]
    ld   [scl], ac
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [tmp]
    ld   [sch], ac
    and  3, ac
    beq  g_o1
    shl
    shl
    shl
    shl
    shl
    or   [tmp], ac
    ld   ac, [tmp]
g_o1:
    ld   [tmp], ac
    ld   ac, [gt]
    ld   0x61, ac
    ld   ac, [colpage]
g_lp:
    ld   g_r0 & 0xFF, ac      ; tile row 0
    ld   ac, [rl]
    ld   g_r0 >> 8, ac
    ld   ac, [rh]
    ld   [gt], x
    ld   LV0 >> 8, y
    ld   [y,x], ac              ; tile id * 8 + 0
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r0:
    ld   g_r1 & 0xFF, ac      ; tile row 1
    ld   ac, [rl]
    ld   g_r1 >> 8, ac
    ld   ac, [rh]
    ld   [gt], x
    ld   LV1 >> 8, y
    ld   [y,x], ac              ; tile id * 8 + 64
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r1:
    ld   g_r2 & 0xFF, ac      ; tile row 2
    ld   ac, [rl]
    ld   g_r2 >> 8, ac
    ld   ac, [rh]
    ld   [gt], x
    ld   LV2 >> 8, y
    ld   [y,x], ac              ; tile id * 8 + 128
    or   [gj], ac
    ld   ac, x
    ld   TS_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   TS_HI >> 8, y
    ld   [y,x], ac
    ld   ac, y
    ld   [tmp], ac
    jmp  ac
g_r2:
    ld   [gj], ac               ; next byte column
    add  1, ac
    and  7, ac
    ld   ac, [gj]
    bne  g_n1
    ld   [gt], ac
    add  1, ac
    and  127, ac
    ld   ac, [gt]
g_n1:
    ld   [colpage], ac
    add  2, ac
    ld   ac, [colpage]
    sub  1, ac
    beq  g_done
    ld   g_lp >> 8, y
    jmp  g_lp
g_done:
drawn_bg:
    ld   hop_3 >> 8, y
    jmp  hop_3                  ; (to the next page)
#addr 0x6300
hop_3:
    ld   LINK_LO, x             ; CALL draw_sprites (RAM)
    ld   f_spr, [x]
    ld   LINK_HI, x
    ld   f_spr >> 8, [x]
    ld   draw_sprites >> 8, y
    jmp  draw_sprites
f_spr:
drawn_all:
    ld   LINK_LO, x             ; CALL snd_update
    ld   f_snd, [x]
    ld   LINK_HI, x
    ld   f_snd >> 8, [x]
    ld   snd_update >> 8, y
    jmp  snd_update
f_snd:
    ld   LINK_LO, x             ; CALL pad_read
    ld   f_pad, [x]
    ld   LINK_HI, x
    ld   f_pad >> 8, [x]
    ld   pad_read >> 8, y
    jmp  pad_read
f_pad:
    ld   LINK_LO, x             ; CALL kbd_scan
    ld   f_kbd, [x]
    ld   LINK_HI, x
    ld   f_kbd >> 8, [x]
    ld   kbd_scan >> 8, y
    jmp  kbd_scan
f_kbd:
    clr  ac
    ld   ac, [inp]
    ld   [R0], ac               ; pad: Right (bit 7), Left (6), Up (4), B (0)
    and  0x80, ac
    beq  i_1
    ld   1, ac
    ld   ac, [inp]
i_1:
    ld   [R0], ac
    and  0x40, ac
    beq  i_2
    ld   [inp], ac
    or   2, ac
    ld   ac, [inp]
i_2:
    ld   [R0], ac
    and  0x11, ac
    bne  i_3
    ld   [R1], ac               ; A (bit 8)
    and  0x01, ac
    beq  i_4
i_3:
    ld   [inp], ac
    or   4, ac
    ld   ac, [inp]
i_4:
    ld   [KBD_NOW + 7], ac      ; Right key (column 7 row 7, 0 = down)
    and  0x80, ac
    bne  k_1
    ld   [inp], ac
    or   1, ac
    ld   ac, [inp]
k_1:
    ld   [KBD_NOW + 7], ac      ; Left (row 5)
    and  0x20, ac
    bne  k_2
    ld   [inp], ac
    or   2, ac
    ld   ac, [inp]
k_2:
    ld   [KBD_NOW + 6], ac      ; Up (column 6 row 5)
    and  0x20, ac
    beq  k_3
    ld   [KBD_NOW + 7], ac      ; Space (column 7 row 2)
    and  0x04, ac
    bne  k_4
k_3:
    ld   [inp], ac
    or   4, ac
    ld   ac, [inp]
k_4:
    ld   [inp], ac              ; any input: the player plays
    beq  i_idle
    clr  ac
    ld   ac, [demo]
    ld   ac, [idle_lo]
    ld   ac, [idle_hi]
    bra  i_mode
i_idle:
    ld   [demo], ac
    bne  i_mode
    ld   [idle_lo], ac
    add  1, ac
    ld   ac, [idle_lo]
    bcc  i_id1
    ld   [idle_hi], ac
    add  1, ac
    ld   ac, [idle_hi]
i_id1:
    ld   [idle_hi], ac
    sub  IDLE_TICKS >> 8, ac
    bne  i_mode
    ld   [idle_lo], ac
    sub  IDLE_TICKS & 0xFF, ac
    bne  i_mode
    ld   1, ac
    ld   ac, [demo]
i_mode:
    ld   LINK_LO, x             ; CALL game
    ld   f_game, [x]
    ld   LINK_HI, x
    ld   f_game >> 8, [x]
    ld   game >> 8, y
    jmp  game
f_game:
    ld   LINK_LO, x             ; CALL hud
    ld   f_hud, [x]
    ld   LINK_HI, x
    ld   f_hud >> 8, [x]
    ld   hud >> 8, y
    jmp  hud
f_hud:
    ld   frame >> 8, y
    jmp  frame

; tile_at: AC = 0 when cell ta_g of world byte column ta_hi:ta_lo is not solid
tile_at:
    ld   hop_4 >> 8, y
    jmp  hop_4                  ; (to the next page)
#addr 0x6400
hop_4:
    ld   [ta_g], ac
    sub  GROUND_G, ac
    bcs  ta_no                  ; above the level band
    ld   ac, [tmp3]
    sub  48, ac
    bcc  ta_no                  ; below it
    ld   [tmp3], ac             ; tile row = (g - 64) / 16 -> page LV0 + row
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    add  LV0 >> 8, ac
    ld   ac, [tmp3]
    ld   [ta_lo], ac            ; tile column = (x >> 3) & 127
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [dlo]
    ld   [ta_hi], ac
    and  3, ac
    shl
    shl
    shl
    shl
    shl
    or   [dlo], ac
    ld   ac, x
    ld   [tmp3], y
    ld   [y,x], ac
    ld   ac, x
    ld   SOLID >> 8, y
    ld   [y,x], ac
    ld   [LINK_HI], y
    jmp  [LINK_LO]
ta_no:
    clr  ac
    ld   [LINK_HI], y
    jmp  [LINK_LO]
reset_objs:
    clr  ac                     ; slimes from the ROM list (OBJ x00-x47)
    ld   ac, [tmp]
ro_1:
    ld   [tmp], x
    ld   OBJ >> 8, y
    ld   [y,x], ac
    ld   ENEMY >> 8, y
    ld   ac, [y,x]
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    sub  0x48, ac
    bne  ro_1
    clr  ac                     ; every coin back
    ld   ac, [tmp]
    ld   COIN_GOT >> 8, y
ro_2:
    ld   [tmp], x
    ld   0, [y,x]
    ld   [tmp], ac
    add  1, ac
    ld   ac, [tmp]
    sub  N_COINS, ac
    bne  ro_2
    ld   [LINK_HI], y
    jmp  [LINK_LO]
respawn:
    ld   [chk_lo], ac           ; at the last place stood on, from the top
    ld   ac, [pxl]
    ld   [chk_hi], ac
    ld   ac, [pxh]
    clr  ac
    ld   ac, [pyh]
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
    ld   ac, [onground]
    ld   ac, [facing]
    ld   INV_FRAMES, ac
    ld   ac, [inv]
    ld   [LINK_HI], y
    jmp  [LINK_LO]

; game: the demo player, then movement, objects, sprite list
game:
    ld   [SP], x                ; PUSH_LINK
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [demo], ac
    bne  gm_demo
    ld   gm_play >> 8, y
    jmp  gm_play
gm_demo:
    ld   1, ac                  ; demo: run right; jump at water, walls, slimes
    ld   ac, [inp]
    ld   [onground], ac
    bne  gm_d0
    ld   gm_play >> 8, y
    jmp  gm_play
gm_d0:
    ld   [danger], ac           ; a slime ahead (seen last frame)
    bne  gm_djump
    ld   [pxl], ac              ; ground ahead? (byte 10, the cell below the feet)
    add  10, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_d1
    add  1, ac
gm_d1:
    ld   ac, [ta_hi]
    ld   [pyh], ac
    add  16, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_d2, [x]
    ld   LINK_HI, x
    ld   gm_d2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_d2:
    beq  gm_djump
    ld   [pyh], ac              ; a wall ahead? (byte 9, the middle row)
    add  8, ac
    ld   ac, [ta_g]
    ld   [ta_lo], ac
    sub  1, ac
    ld   ac, [ta_lo]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_d3, [x]
    ld   LINK_HI, x
    ld   gm_d3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_d3:
    beq  gm_play_j
gm_djump:
    ld   5, ac
    ld   ac, [inp]
gm_play_j:
    ld   gm_play >> 8, y
    jmp  gm_play

; game: the player, sideways
gm_play:
    ld   hop_5 >> 8, y
    jmp  hop_5                  ; (to the next page)
#addr 0x6500
hop_5:
    clr  ac
    ld   ac, [moved]
    ld   [inp], ac              ; right
    and  1, ac
    beq  gm_nr
    clr  ac
    ld   ac, [facing]
    ld   [pxl], ac              ; wall at byte 8, rows 1, 8, 15?
    add  8, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_r1
    add  1, ac
gm_r1:
    ld   ac, [ta_hi]
    ld   1, ac
    ld   ac, [moved]
    bra  gm_side
gm_nr:
    ld   [inp], ac              ; left
    and  2, ac
    bne  gm_l0
    ld   gm_vert >> 8, y
    jmp  gm_vert
gm_l0:
    ld   5, ac
    ld   ac, [facing]
    ld   [pxl], ac              ; wall at byte -1?
    sub  1, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_l1
    sub  1, ac
gm_l1:
    ld   ac, [ta_hi]
    ld   2, ac
    ld   ac, [moved]
gm_side:
    ld   [pyh], ac
    add  1, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_s1, [x]
    ld   LINK_HI, x
    ld   gm_s1 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_s1:
    bne  gm_block
    ld   [pyh], ac
    add  8, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_s2, [x]
    ld   LINK_HI, x
    ld   gm_s2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_s2:
    bne  gm_block
    ld   [pyh], ac
    add  15, ac
    ld   ac, [ta_g]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_s3, [x]
    ld   LINK_HI, x
    ld   gm_s3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_s3:
    bne  gm_block
    ld   [moved], ac            ; free: move one byte column (wraps at 1024)
    sub  1, ac
    bne  gm_ml
    ld   [pxl], ac
    add  1, ac
    ld   ac, [pxl]
    bne  gm_vert_j
    ld   [pxh], ac
    add  1, ac
    and  3, ac
    ld   ac, [pxh]
    bne  gm_vert_j
    ld   LINK_LO, x             ; x = 0: a new lap, coins and slimes back
    ld   gm_vert & 0xFF, [x]
    ld   LINK_HI, x
    ld   gm_vert >> 8, [x]
    ld   reset_objs >> 8, y
    jmp  reset_objs
gm_ml:
    ld   [pxl], ac
    sub  1, ac
    ld   ac, [pxl]
    xor  0xFF, ac
    bne  gm_vert_j
    ld   [pxh], ac
    sub  1, ac
    and  3, ac
    ld   ac, [pxh]
    bra  gm_vert_j
gm_block:
    clr  ac
    ld   ac, [moved]
gm_vert_j:
    ld   gm_vert >> 8, y
    jmp  gm_vert

; game: jumping and falling
gm_vert:
    ld   hop_6 >> 8, y
    jmp  hop_6                  ; (to the next page)
#addr 0x6600
hop_6:
    ld   [inp], ac              ; jump from the ground
    and  4, ac
    beq  gm_g0
    ld   [onground], ac
    beq  gm_g0
    ld   JUMPV_LO, ac
    ld   ac, [vyl]
    ld   JUMPV_HI, ac
    ld   ac, [vyh]
    ld   72, ac
    ld   LINK_LO, x             ; CALL snd_beep
    ld   gm_js, [x]
    ld   LINK_HI, x
    ld   gm_js >> 8, [x]
    ld   snd_beep >> 8, y
    jmp  snd_beep
gm_js:
gm_g0:
    ld   [vyl], ac              ; gravity
    add  GRAV, ac
    ld   ac, [vyl]
    ld   [vyh], ac
    bcc  gm_g1
    add  1, ac
gm_g1:
    ld   ac, [vyh]
    blt  gm_g2                  ; going up
    sub  MAXFALL_HI, ac
    bcs  gm_g2
    ld   MAXFALL_HI, ac
    ld   ac, [vyh]
    clr  ac
    ld   ac, [vyl]
gm_g2:
    ld   [pyl], ac              ; y += vy
    add  [vyl], ac
    ld   ac, [pyl]
    ld   [vyh], ac
    blt  gm_up
    ld   [pyh], ac
    bcc  gm_g3
    add  1, ac
gm_g3:
    add  [vyh], ac
    ld   ac, [pyh]
    ld   gm_fall >> 8, y
    jmp  gm_fall
gm_up:
    ld   [pyh], ac              ; (vy < 0: high byte - 1 + carry)
    bcs  gm_g4
    sub  1, ac
gm_g4:
    add  [vyh], ac
    ld   ac, [pyh]
    blt  gm_top                 ; above the screen: stop there
    ld   gm_head >> 8, y
    jmp  gm_head
gm_top:
    clr  ac
    ld   ac, [pyh]
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
    ld   gm_obj >> 8, y
    jmp  gm_obj
gm_head:
    ld   [pyh], ac              ; head in a solid tile?
    ld   ac, [ta_g]
    ld   [pxl], ac
    add  1, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_h1
    add  1, ac
gm_h1:
    ld   ac, [ta_hi]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_h2, [x]
    ld   LINK_HI, x
    ld   gm_h2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_h2:
    bne  gm_bump
    ld   [ta_lo], ac
    add  5, ac
    ld   ac, [ta_lo]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_h3, [x]
    ld   LINK_HI, x
    ld   gm_h3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_h3:
    beq  gm_h4
gm_bump:
    ld   [pyh], ac              ; below that tile
    sub  GROUND_G, ac
    and  0xF0, ac
    add  GROUND_G + 16, ac
    ld   ac, [pyh]
    clr  ac
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
gm_h4:
    clr  ac
    ld   ac, [onground]
    ld   gm_obj >> 8, y
    jmp  gm_obj
DROWN_G    = 100
    ld   hop_7 >> 8, y
    jmp  hop_7                  ; (to the next page)
#addr 0x6700
hop_7:
gm_fall:
    ld   [pyh], ac              ; into the water: a life
    sub  DROWN_G, ac
    bcs  gm_f0
    ld   LINK_LO, x
    ld   gm_obj & 0xFF, [x]
    ld   LINK_HI, x
    ld   gm_obj >> 8, [x]
    ld   lose_life >> 8, y
    jmp  lose_life
gm_f0:
    ld   [pyh], ac              ; feet on a solid tile?
    add  16, ac
    ld   ac, [ta_g]
    ld   [pxl], ac
    add  1, ac
    ld   ac, [ta_lo]
    ld   [pxh], ac
    bcc  gm_f1
    add  1, ac
gm_f1:
    ld   ac, [ta_hi]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_f2, [x]
    ld   LINK_HI, x
    ld   gm_f2 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_f2:
    bne  gm_land
    ld   [ta_lo], ac
    add  5, ac
    ld   ac, [ta_lo]
    ld   LINK_LO, x             ; CALL tile_at
    ld   gm_f3, [x]
    ld   LINK_HI, x
    ld   gm_f3 >> 8, [x]
    ld   tile_at >> 8, y
    jmp  tile_at
gm_f3:
    bne  gm_land
    clr  ac
    ld   ac, [onground]
    ld   gm_obj >> 8, y
    jmp  gm_obj
gm_land:
    ld   [pyh], ac              ; stand on the tile: y = its top - 16
    add  16 - GROUND_G, ac
    and  0xF0, ac
    add  GROUND_G - 16, ac
    ld   ac, [pyh]
    clr  ac
    ld   ac, [pyl]
    ld   ac, [vyl]
    ld   ac, [vyh]
    ld   1, ac
    ld   ac, [onground]
    ld   [pxl], ac              ; checkpoint
    ld   ac, [chk_lo]
    ld   [pxh], ac
    ld   ac, [chk_hi]
    ld   gm_obj >> 8, y
    jmp  gm_obj

; lose_life: a life (game over: a new game), noise, respawn; returns via LINK
lose_life:
    ld   [LINK_LO], ac          ; keep the return address over snd_noise
    ld   ac, [ll_lo]
    ld   [LINK_HI], ac
    ld   ac, [ll_hi]
    ld   1, ac
    ld   ac, [hud_dirty]
    ld   [lives], ac
    sub  1, ac
    ld   ac, [lives]
    bne  ll_1
    ld   3, ac                  ; game over: a new game
    ld   ac, [lives]
    clr  ac
    ld   ac, [score_lo]
    ld   ac, [score_hi]
    ld   ac, [coins]
ll_1:
    ld   8, ac                  ; noise: rumble, 30 frames, fading
    ld   ac, [R0]
    ld   30, ac
    ld   ac, [R2]
    ld   3, ac
    ld   ac, [R3]
    ld   90, ac
    ld   LINK_LO, x             ; CALL snd_noise
    ld   ll_2, [x]
    ld   LINK_HI, x
    ld   ll_2 >> 8, [x]
    ld   snd_noise >> 8, y
    jmp  snd_noise
ll_2:
    ld   [ll_lo], ac
    ld   ac, [LINK_LO]
    ld   [ll_hi], ac
    ld   ac, [LINK_HI]
    ld   respawn >> 8, y
    jmp  respawn
sl_add:
    ld   [sl_n], ac
    sub  MAX_SPR, ac
    beq  sa_full
    ld   [sl_n], ac
    add  SL_C, x
    ld   [dlo], ac
    ld   ac, [x]
    ld   [sl_n], ac
    add  SL_G, x
    ld   [tmp3], ac
    ld   ac, [x]
    ld   [tmp], x
    ld   FR_LO >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp2]
    ld   [sl_n], ac
    add  SL_LO, x
    ld   [tmp2], ac
    ld   ac, [x]
    ld   [tmp], x
    ld   FR_HI >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp2]
    ld   [sl_n], ac
    add  SL_HI, x
    ld   [tmp2], ac
    ld   ac, [x]
    ld   [sl_n], ac
    add  1, ac
    ld   ac, [sl_n]
sa_full:
    ld   [LINK_HI], y
    jmp  [LINK_LO]

; game: camera, coins
gm_obj:
    ld   hop_8 >> 8, y
    jmp  hop_8                  ; (to the next page)
#addr 0x6800
hop_8:
    ld   [onground], ac         ; animation: count while running on the ground
    beq  go_a1
    ld   [moved], ac
    beq  go_a1
    ld   [anim], ac
    add  1, ac
    ld   ac, [anim]
go_a1:
    ld   [inv], ac
    beq  go_a2
    sub  1, ac
    ld   ac, [inv]
go_a2:
    ld   [pxl], ac              ; camera: scroll = px - 30 (the player at
    sub  30, ac                 ; screen byte column 30)
    ld   ac, [scl]
    ld   [pxh], ac
    bcc  go_a3
    sub  1, ac
go_a3:
    and  3, ac
    ld   ac, [sch]
    clr  ac
    ld   ac, [sl_n]
    ld   ac, [o_i]
    ld   ac, [danger]
go_c:
    ld   [o_i], x               ; coin o_i: taken?
    ld   COIN_GOT >> 8, y
    ld   [y,x], ac
    beq  go_c0
    ld   go_cn >> 8, y
    jmp  go_cn
go_c0:
    ld   OBJ >> 8, y
    ld   [o_i], ac
    add  COIN_XH, x
    ld   [y,x], ac
    ld   ac, [dhi]
    ld   [o_i], ac
    add  COIN_XL, x
    ld   [y,x], ac
    sub  [scl], ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_cn_sc_1
    sub  1, ac
go_cn_sc_1:
    sub  [sch], ac
    ld   ac, [dhi]
    ld   [dlo], ac
    add  8, ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_cn_sc_2
    add  1, ac
go_cn_sc_2:
    and  3, ac
    bne  go_cn_sc_off
    ld   [dlo], ac
    sub  88, ac
    bcs  go_cn_sc_on
go_cn_sc_off:
    ld   go_cn >> 8, y
    jmp  go_cn
go_cn_sc_on:
    ld   OBJ >> 8, y            ; top cell + 32
    ld   [o_i], ac
    add  COIN_G, x
    ld   [y,x], ac
    add  32, ac
    ld   ac, [tmp3]
    ld   [dlo], ac              ; touching the player?  cx - px = dlo - 38,
    sub  35, ac                 ; in -3..6
    sub  10, ac
    bcc  go_cadd
    ld   [tmp3], ac             ; cg - pyh in -7..15: (cg + 32) - pyh - 25
    sub  [pyh], ac
    sub  25, ac
    sub  23, ac
    bcc  go_cadd
    ld   [o_i], x               ; taken: +10, a beep
    ld   COIN_GOT >> 8, y
    ld   1, [y,x]
    ld   [coins], ac
    add  1, ac
    ld   ac, [coins]
    ld   [score_lo], ac
    add  10, ac
    ld   ac, [score_lo]
    bcc  go_cs
    ld   [score_hi], ac
    add  1, ac
    ld   ac, [score_hi]
go_cs:
    ld   1, ac
    ld   ac, [hud_dirty]
    ld   LINK_LO, x
    ld   go_cn & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_cn >> 8, [x]
    ld   88, ac
    ld   snd_beep >> 8, y
    jmp  snd_beep
go_cadd:
    ld   [FRAME_LO], ac         ; frame: coin1-4, a step every 8 frames
    shr  ac
    shr  ac
    shr  ac
    and  3, ac
    add  FID_COIN, ac
    ld   ac, [tmp]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_ca1, [x]
    ld   LINK_HI, x
    ld   go_ca1 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_ca1:
go_cn:
    ld   [o_i], ac
    add  1, ac
    ld   ac, [o_i]
    sub  N_COINS, ac
    beq  go_cd
    ld   go_c >> 8, y
    jmp  go_c
go_cd:
    clr  ac
    ld   ac, [o_i]
    ld   go_e >> 8, y
    jmp  go_e

; game: slimes
go_e:
    ld   hop_9 >> 8, y
    jmp  hop_9                  ; (to the next page)
#addr 0x6900
hop_9:
    ld   ENEMY >> 8, y          ; alive?
    ld   [o_i], ac
    add  0x40, x
    ld   [y,x], ac
    bne  go_e1
    ld   go_en >> 8, y
    jmp  go_en
go_e1:
    ld   [FRAME_LO], ac         ; move a byte every other frame
    and  1, ac
    beq  go_e5
    ld   [o_i], ac
    add  0x18, x
    ld   [y,x], ac              ; direction 0 right, 1 left
    bne  go_el
    ld   [o_i], x               ; right: x + 1
    ld   [y,x], ac
    add  1, ac
    ld   ac, [y,x]
    bne  go_e2
    ld   [o_i], ac
    add  8, x
    ld   [y,x], ac
    add  1, ac
    and  3, ac
    ld   ac, [y,x]
go_e2:
    ld   [o_i], ac              ; at the right end: turn
    add  0x30, x
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   [o_i], x
    ld   [y,x], ac
    sub  [tmp], ac
    bne  go_e5
    ld   [o_i], ac
    add  0x18, x
    ld   1, [y,x]
    bra  go_e5
go_el:
    ld   [o_i], x               ; left: x - 1
    ld   [y,x], ac
    sub  1, ac
    ld   ac, [y,x]
    xor  0xFF, ac
    bne  go_e3
    ld   [o_i], ac
    add  8, x
    ld   [y,x], ac
    sub  1, ac
    and  3, ac
    ld   ac, [y,x]
go_e3:
    ld   [o_i], ac              ; at the left end: turn
    add  0x20, x
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   [o_i], x
    ld   [y,x], ac
    sub  [tmp], ac
    bne  go_e5
    ld   [o_i], ac
    add  0x18, x
    ld   0, [y,x]
go_e5:
    ld   ENEMY >> 8, y
    ld   [o_i], ac
    add  8, x
    ld   [y,x], ac
    ld   ac, [dhi]
    ld   [o_i], ac
    add  0, x
    ld   [y,x], ac
    sub  [scl], ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_en_sc_1
    sub  1, ac
go_en_sc_1:
    sub  [sch], ac
    ld   ac, [dhi]
    ld   [dlo], ac
    add  8, ac
    ld   ac, [dlo]
    ld   [dhi], ac
    bcc  go_en_sc_2
    add  1, ac
go_en_sc_2:
    and  3, ac
    bne  go_en_sc_off
    ld   [dlo], ac
    sub  88, ac
    bcs  go_en_sc_on
go_en_sc_off:
    ld   go_en >> 8, y
    jmp  go_en
go_en_sc_on:
    ld   ENEMY >> 8, y          ; top cell + 32
    ld   [o_i], ac
    add  0x10, x
    ld   [y,x], ac
    add  32, ac
    ld   ac, [tmp3]
    sub  [pyh], ac              ; eg - pyh, in tmp2
    sub  32, ac
    ld   ac, [tmp2]
    ld   [dlo], ac              ; ahead of the player (4-24 bytes) at about
    sub  42, ac                 ; the same height: danger, for the demo
    sub  21, ac
    bcc  go_e6
    ld   [tmp2], ac
    add  15, ac
    sub  31, ac
    bcc  go_e6
    ld   1, ac
    ld   ac, [danger]
go_e6:
    ld   [inv], ac              ; touching the player?  ex - px in -6..6
    bne  go_eadd
    ld   [dlo], ac
    sub  32, ac
    sub  13, ac
    bcc  go_eadd
    ld   [tmp2], ac             ; eg - pyh in -14..14
    add  14, ac
    sub  29, ac
    bcc  go_eadd
    ld   go_hit >> 8, y
    jmp  go_hit
go_eadd:
    ld   [FRAME_LO], ac         ; slime1 / slime2, 16 frames each
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    and  1, ac
    add  FID_SLIME, ac
    ld   ac, [tmp]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_ea1, [x]
    ld   LINK_HI, x
    ld   go_ea1 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_ea1:
    ld   hop_10 >> 8, y
    jmp  hop_10                  ; (to the next page)
#addr 0x6A00
hop_10:
go_en:
    ld   [o_i], ac
    add  1, ac
    ld   ac, [o_i]
    sub  N_SLIMES, ac
    beq  go_pl_j
    ld   go_e >> 8, y
    jmp  go_e
go_pl_j:
    ld   go_pl >> 8, y
    jmp  go_pl

; game: a slime touches the player; the player into the list
go_hit:
    ld   [vyh], ac              ; falling and feet in its top half: stomp
    blt  go_hurt
    ld   [tmp2], ac             ; eg - pyh >= 8
    sub  8, ac
    blt  go_hurt
    ld   ENEMY >> 8, y
    ld   [o_i], ac
    add  0x40, x
    ld   0, [y,x]
    ld   0xFD, ac               ; bounce up
    ld   ac, [vyh]
    clr  ac
    ld   ac, [vyl]
    ld   [score_lo], ac         ; +100
    add  100, ac
    ld   ac, [score_lo]
    bcc  go_h1
    ld   [score_hi], ac
    add  1, ac
    ld   ac, [score_hi]
go_h1:
    ld   1, ac
    ld   ac, [hud_dirty]
    ld   LINK_LO, x
    ld   go_en & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_en >> 8, [x]
    ld   60, ac
    ld   snd_beep >> 8, y
    jmp  snd_beep
go_hurt:
    ld   LINK_LO, x
    ld   go_eadd & 0xFF, [x]
    ld   LINK_HI, x
    ld   go_eadd >> 8, [x]
    ld   lose_life >> 8, y
    jmp  lose_life
go_pl:
    ld   [inv], ac              ; the player last (blinks while safe)
    and  4, ac
    bne  go_done
    ld   38, ac                 ; byte column 30 + 8
    ld   ac, [dlo]
    ld   [pyh], ac
    add  32, ac
    ld   ac, [tmp3]
    ld   [onground], ac         ; frame: jump, run 1-3, stand
    bne  go_p1
    ld   4, ac
    bra  go_p3
go_p1:
    ld   [moved], ac
    beq  go_p3
    ld   [anim], ac             ; run: 1, 2, 3, 2 a step every 4 frames
    shr  ac
    shr  ac
    and  3, ac
    ld   ac, x
    ld   RUNSEQ >> 8, y
    ld   [y,x], ac
go_p3:
    add  [facing], ac
    ld   ac, [tmp]
    ld   LINK_LO, x             ; CALL sl_add
    ld   go_p4, [x]
    ld   LINK_HI, x
    ld   go_p4 >> 8, [x]
    ld   sl_add >> 8, y
    jmp  sl_add
go_p4:
go_done:
    ld   lib_leave >> 8, y
    jmp  lib_leave

; hud: score line when it changed, CPU load every 16 frames
hud:
    ld   [SP], x                ; PUSH_LINK
    ld   [LINK_HI], ac
    ld   ac, [x]
    ld   [SP], ac
    dec
    ld   ac, x
    dec
    ld   ac, [SP]
    ld   [LINK_LO], ac
    ld   ac, [x]
    ld   [hud_dirty], ac
    bne  hu_s
    ld   hu_cpu >> 8, y
    jmp  hu_cpu
hu_s:
    clr  ac
    ld   ac, [hud_dirty]
    ld   6, ac                  ; score at column 6
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   [score_lo], ac
    ld   ac, [R0]
    ld   [score_hi], ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_dec16
    ld   hu_1, [x]
    ld   LINK_HI, x
    ld   hu_1 >> 8, [x]
    ld   con_dec16 >> 8, y
    jmp  con_dec16
hu_1:
    ld   s_sp >> 8, ac
    ld   ac, [R1]
    ld   s_sp, ac
    ld   ac, [R0]
    ld   LINK_LO, x             ; CALL con_puts
    ld   hu_2, [x]
    ld   LINK_HI, x
    ld   hu_2 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
hu_2:
    ld   22, ac                 ; coins at column 22
    ld   ac, [CUR_COL]
    ld   [coins], ac
    ld   LINK_LO, x             ; CALL con_dec8
    ld   hu_3, [x]
    ld   LINK_HI, x
    ld   hu_3 >> 8, [x]
    ld   con_dec8 >> 8, y
    jmp  con_dec8
hu_3:
    ld   s_sp >> 8, ac
    ld   ac, [R1]
    ld   s_sp, ac
    ld   ac, [R0]
    ld   hop_11 >> 8, y
    jmp  hop_11                  ; (to the next page)
#addr 0x6B00
hop_11:
    ld   LINK_LO, x             ; CALL con_puts
    ld   hu_4, [x]
    ld   LINK_HI, x
    ld   hu_4 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
hu_4:
    ld   37, ac                 ; lives at column 37
    ld   ac, [CUR_COL]
    ld   [lives], ac
    ld   LINK_LO, x             ; CALL con_dec8
    ld   hu_5, [x]
    ld   LINK_HI, x
    ld   hu_5 >> 8, [x]
    ld   con_dec8 >> 8, y
    jmp  con_dec8
hu_5:
    ld   56, ac                 ; demo / player at column 56
    ld   ac, [CUR_COL]
    ld   s_demo, ac
    ld   ac, [R0]
    ld   [demo], ac
    bne  hu_6
    ld   s_you, ac
    ld   ac, [R0]
hu_6:
    ld   s_demo >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   hu_7, [x]
    ld   LINK_HI, x
    ld   hu_7 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
hu_7:
hu_cpu:
    ld   [hud_div], ac          ; CPU load every 16 frames:
    sub  1, ac                  ; busy % = 100 - polls / POLLS_PER_PCT
    ld   ac, [hud_div]
    beq  hu_c0
    ld   lib_leave >> 8, y
    jmp  lib_leave
hu_c0:
    ld   16, ac
    ld   ac, [hud_div]
    ld   100, ac
    ld   ac, [tmp3]
hu_c1:
    ld   [it_lo], ac            ; polls - POLLS_PER_PCT until it goes below 0
    sub  POLLS_PER_PCT, ac
    ld   ac, [it_lo]
    ld   [it_hi], ac
    bcc  hu_c2
    sub  1, ac
    ld   ac, [it_hi]
    blt  hu_c3
hu_c2:
    ld   [tmp3], ac
    sub  1, ac
    ld   ac, [tmp3]
    beq  hu_c3
    bra  hu_c1
hu_c3:
    ld   10, ac
    ld   ac, [CUR_COL]
    ld   3, ac
    ld   ac, [CUR_ROW]
    ld   [tmp3], ac
    ld   LINK_LO, x             ; CALL con_dec8
    ld   hu_8, [x]
    ld   LINK_HI, x
    ld   hu_8 >> 8, [x]
    ld   con_dec8 >> 8, y
    jmp  con_dec8
hu_8:
    ld   s_pct >> 8, ac
    ld   ac, [R1]
    ld   s_pct, ac
    ld   ac, [R0]
    ld   LINK_LO, x             ; CALL con_puts
    ld   hu_9, [x]
    ld   LINK_HI, x
    ld   hu_9 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
hu_9:
    ld   lib_leave >> 8, y
    jmp  lib_leave

; text
#addr 0x6C00
s_demo:  #d "DEMO PLAYER", 0x00
s_you:   #d "YOU PLAY   ", 0x00
s_title: #d "PLACARD RUNNER   160 X 112, 16 COLORS, 4 PARALLAX LAYERS, ALL SPRITES IN SOFTWARE", 0x00
s_score: #d "SCORE 0          COINS 0        LIVES 3", 0x00
s_keys:  #d "ARROWS OR SNES PAD: RUN LEFT/RIGHT, UP/SPACE/B JUMP.  STOMP THE SLIMES", 0x00
s_cpu:   #d "CPU BUSY     (WHOLE SCREEN REDRAWN EVERY FRAME, AHEAD OF THE BEAM)", 0x00
s_sp:    #d "  ", 0x00
s_pct:   #d "% ", 0x00

